static void syscall_(Code *c) {
	c8(c,0x0F);
	c8(c,0x05);
}
static size_t je_rel32(Code *c) {
	c8(c,0x0F);
	c8(c,0x84);
	size_t pos=cpos(c);
	c32(c,0);
	return pos;
}

