static void tbeg(Code *c) {
	c8(c,0x48); c8(c,0xBD); c64(c, IN_BASE);
}

static void tend(Code *c, Gen *g, int update_status) {
	c8(c,0x4C); c8(c,0x89); c8(c,0xF8);
	if(update_status) store_status_rax(c,g);
}

static char g_tem[600];

static int topt(Stage *st, const char *fl, const char *wa, char *o, char **ov, StrV *fs) {
	int i = 1;
	g_tem[0] = '\0';
	for(; i<st->argv.n; i++) {
		char *a = st->argv.v[i];
		if(strcmp(a,"--")==0) { i++; break; }
		if(a[0]!='-' || !a[1]) {
			sv_push(fs, a);
			continue;
		}
		if(a[1]=='-') {
			char *eq = strchr(a, '=');
			size_t nl = eq ? (size_t)(eq-a-2) : strlen(a+2);
			const char *w = wa;
			int hit = 0;
			while(w && *w) {
				const char *e = strchr(w, ',');
				size_t l = e ? (size_t)(e-w) : strlen(w);
				if(l-1==nl && strncmp(a+2, w+1, nl)==0) {
					hit = 1;
					char f = w[0];
					o[(uint8_t)f] = 1;
					const char *d = strchr(fl, f);
					if(d && d[1]==':') {
						if(eq) ov[(uint8_t)f] = eq+1;
						else if(i+1<st->argv.n) ov[(uint8_t)f] = st->argv.v[++i];
						else if(!g_tem[0]) snprintf(g_tem, sizeof(g_tem), "%s: option '%.*s' requires an argument\n", st->argv.v[0], (int)(nl+2), a);
					}
					break;
				}
				w = e ? e+1 : NULL;
			}
			if(!hit && !g_tem[0]) snprintf(g_tem, sizeof(g_tem), "%s: unrecognized option '%s'\n", st->argv.v[0], a);
			continue;
		}
		if(a[1]>='0' && a[1]<='9' && strchr(fl, '#')) {
			o['#'] = 1;
			ov['#'] = a+1;
			continue;
		}
		for(char *q = a+1; *q; q++) {
			const char *d = strchr(fl, *q);
			if(!d || *q==':' || *q=='#') {
				if(!g_tem[0]) snprintf(g_tem, sizeof(g_tem), "%s: invalid option -- '%c'\n", st->argv.v[0], *q);
				continue;
			}
			o[(uint8_t)*q] = 1;
			if(d[1]==':') {
				if(q[1]) ov[(uint8_t)*q] = q+1;
				else if(i+1<st->argv.n) ov[(uint8_t)*q] = st->argv.v[++i];
				else if(!g_tem[0]) snprintf(g_tem, sizeof(g_tem), "%s: option requires an argument -- '%c'\n", st->argv.v[0], *q);
				break;
			}
		}
	}
	for(; i<st->argv.n; i++) sv_push(fs, st->argv.v[i]);
	return fs->n;
}

static int topte(Code *c, Gen *g, int us) {
	if(!g_tem[0]) return 0;
	char m[800];
	char nm[64];
	size_t k = strcspn(g_tem, ":");
	if(k>63) k = 63;
	memcpy(nm, g_tem, k);
	nm[k] = '\0';
	snprintf(m, sizeof(m), "%sTry '%s --help' for more information.\n", g_tem, nm);
	wlit2(c,g,m);
	if(us) store_status_imm(c,g,1);
	return 1;
}

