static uint32_t nlsty(const char *s, char d) {
	if(!s) return (uint8_t)d;
	if(strcmp(s,"a")==0 || strcmp(s,"t")==0 || strcmp(s,"n")==0) return (uint8_t)s[0];
	fprintf(stderr, "sh2elf: nl: unsupported numbering style: %s\n", s);
	return 'n';
}

