	if(ov['i']) {
		char *e;
		s1 = s2 = strtoull(ov['i'], &e, 0);
		if(*e==':') s2 = strtoull(e+1, NULL, 0);
	}
	if(fs.n>2) s1 = strtoull(fs.v[2], NULL, 0);
	if(fs.n>3) s2 = strtoull(fs.v[3], NULL, 0);
	if(ov['n']) lim = strtoull(ov['n'], NULL, 0);
