	char pre[1024], e1[600], e2[600];
	snprintf(pre, sizeof(pre), "%s %s differ: byte ", f1, f2);
	snprintf(e1, sizeof(e1), "cmp: EOF on \xE2\x80\x98%s\xE2\x80\x99 ", f1);
	snprintf(e2, sizeof(e2), "cmp: EOF on \xE2\x80\x98%s\xE2\x80\x99 ", f2);
	tini(c,g);
	tsl(c,g,f1,"cmp: %s");
	c8(c,0x49); c8(c,0x89); c8(c,0xEE);
	tsl(c,g,f2,"cmp: %s");
	c8(c,0x4D); c8(c,0x85); c8(c,0xFF);
	size_t jz = je_rel32(c);
	c8(c,0x41); c8(c,0xBF); c32(c,2);
	size_t je = jmp_rel32(c);
	patch_here(c,jz);
